entries[25835] = { ["name"] = "Wanderstab des Forschers", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n132 - 199 Schaden Tempo 2.30\n(71.96 Schaden pro Sekunde)\n+51 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 62\nBenötigt Expedition des Cenarius\n- Wohlwollend\nErhöht die Angriffskraft um 240 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die Angriffskraft um 68.\nAnlegen: Lauftempo ein wenig erhöht." }
