entries[25848] = { ["name"] = "Formel: Runenverzierte Adamantitrute", ["text"] = "Benötigt Verzauberkunst (350)\nBenutzen: Lehrt Euch die Herstellung einer runenverzierten Adamantitrute.\nRunenverzierte Adamantitrute\nWird beim Aufheben gebunden\nBenötigt Verzauberkunst (350)\n\"Kann auch wie jede geringere runenverzierte Rute verwendet werden.\"\nBenötigt Adamantitrute , Große Planaressenz (8), Großer Prismasplitter (8), Urmacht , Runenverzierte Teufelseisenrute" }
